// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

contract VariableTypes {

    // -----------------------------
    // STATE VARIABLES
    // Stored permanently on blockchain
    // -----------------------------
    uint public stateNumber = 100;
    address public owner = msg.sender;

    // -----------------------------
    // FUNCTION TO DEMONSTRATE VARIABLES
    // -----------------------------
    function showVariables(uint _input) public view returns (
        uint localNumber,
        uint stateValue,
        address globalSender,
        uint globalTimestamp
    ) {

        // -----------------------------
        // LOCAL VARIABLE
        // Exists only inside this function
        // -----------------------------
        uint temp = _input + 10;

        // -----------------------------
        // GLOBAL VARIABLES
        // Provided by blockchain
        // -----------------------------
        address sender = msg.sender;
        uint time = block.timestamp;

        return (
            temp,              // local variable
            stateNumber,       // state variable
            sender,            // global variable
            time
                           // global variable
        );
    }
}

